  window.importInvoiceFont=function(input){const file=input.files?.[0];if(!file)return;const ext=(file.name.split('.').pop()||'').toLowerCase();if(!['ttf','otf','woff','woff2'].includes(ext)){showTmError('فقط فایل‌های TTF، OTF، WOFF و WOFF2 پذیرفته می‌شوند.');input.value='';return}if(file.size<=0||file.size>1024*1024){showTmError('حجم هر فایل فونت باید بیشتر از صفر و حداکثر ۱ مگابایت باشد.');input.value='';return}const reader=new FileReader();reader.onload=()=>{try{const bytes=new Uint8Array(reader.result),sig=Array.from(bytes.slice(0,4));const validSig=ext==='ttf'?(sig.join(',')==='0,1,0,0'||String.fromCharCode(...sig)==='true'||String.fromCharCode(...sig)==='typ1'):ext==='otf'?String.fromCharCode(...sig)==='OTTO':ext==='woff'?String.fromCharCode(...sig)==='wOFF':String.fromCharCode(...sig)==='wOF2';if(!validSig)throw new Error('signature');let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));const b64=btoa(binary),id='uploaded-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),name=file.name.replace(/\.[^.]+$/,'').replace(/[<>]|javascript:|[{}]/ig,'').slice(0,80)||`فونت ${ext.toUpperCase()}`,mime={ttf:'ttf',otf:'otf',woff:'woff',woff2:'woff2'}[ext];const previousFonts=state.settings.invoiceFonts.slice();state.settings.invoiceFonts.push({id,name,format:ext,dataUrl:`data:font/${mime};base64,${b64}`});try{if(typeof save==='function')save();else localStorage.setItem('tameshk-state',JSON.stringify(state))}catch(e){state.settings.invoiceFonts=previousFonts;throw e}refreshFontFaces();refreshTemplateManager();refreshFontManager();showToast('فونت محلی به فهرست فونت‌های فاکتور افزوده شد.')}catch(e){showTmError('فایل فونت معتبر نیست یا بارگذاری/ذخیرهٔ آن ممکن نشد؛ فضای ذخیره‌سازی محلی را بررسی کنید.')}finally{input.value=''}};reader.onerror=()=>{showTmError('خواندن فایل فونت ممکن نشد.');input.value=''};reader.readAsArrayBuffer(file)}
