  function fieldListMarkup(t){return t.fields.map((f,i)=>{const ty=safeTypography(f),label=fieldLabel(t,f);return `<div class="tm-field"><span class="muted">${i+1}</span><div class="tm-field-edit"><input value="${esc(label)}" maxlength="${LIMITS.label}" onchange="updateInvoiceFieldLabel('${esc(f.id)}',this.value)"><label class="tm-visible-toggle"><input type="checkbox" ${f.visible?'checked':''} onchange="updateInvoiceFieldVisibility('${esc(f.id)}',this.checked)">نمایش فیلد</label><small>${esc(f.source)} · ${esc(f.type)}</small><div class="tm-typography"><label>فونت<select onchange="updateInvoiceFieldStyle('${esc(f.id)}','fontId',this.value)">${fontOptions(ty.fontId)}</select></label><label>اندازه (pt)<input type="number" min="7" max="28" value="${ty.fontSize}" onchange="updateInvoiceFieldStyle('${esc(f.id)}','fontSize',this.value)"></label><label>رنگ<input type="color" value="${ty.color}" onchange="updateInvoiceFieldStyle('${esc(f.id)}','color',this.value)"></label></div></div><div class="toolbar"><button class="btn small" onclick="moveInvoiceField('${esc(f.id)}',-1)" ${i===0?'disabled':''}>▲</button><button class="btn small" onclick="moveInvoiceField('${esc(f.id)}',1)" ${i===t.fields.length-1?'disabled':''}>▼</button><button class="btn small danger" onclick="removeInvoiceField('${esc(f.id)}')">×</button></div></div>`}).join('')}
