  window.addInvoiceField=function(){const t=editableTemplate();const source=document.getElementById('tmAddSource')?.value||'invoice.number';if(t.fields.length>=LIMITS.fields)return showTmError('تعداد فیلدها نمی‌تواند بیشتر از ۳۲ باشد.');const meta=SOURCES[source];let id=source.replace(/[^a-z0-9]+/g,'-')+'-'+Date.now().toString(36);t.fields.push({id,source,type:meta.type,label:meta.label,visible:true,style:{align:'right',emphasis:'normal',tone:'default'},...safeTypography({})});if(t.producerDefaults)t.producerDefaults.labels[id]=meta.label;persistTemplate(t);clearTmError();refreshTemplateManager();showToast('فیلد به قالب اضافه شد.')};
